SELECT DATE_TRUNC('MONTH', p.launch_date) AS launch_month, CASE WHEN p.price >= 1050 THEN 'high' WHEN p.price >= 600 THEN 'mid' ELSE 'low' END AS price_bucket, ROUND(AVG(i.quantity), 2) AS avg_quantity, SUM(i.quantity) AS total_quantity FROM inventory i LEFT JOIN products p ON i.product_id = p.id INNER JOIN suppliers s ON s.id = p.supplier_id GROUP BY DATE_TRUNC('MONTH', p.launch_date), CASE WHEN p.price >= 1050 THEN 'high' WHEN p.price >= 600 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(i.quantity), 2) > 27
